{
  "title": "Discussion on tax filing, domain purchase, and low‑profit app ideas",
  "topics": [
    {
      "id": "tax-filing",
      "title": "Tax filing process and potential shortcuts",
      "claims": [
        {
          "text": "Paying 500 UAH to aunt Sveta can reduce the large main‑penalty caused by mis‑declared columns.",
          "evidence": [1]
        },
        {
          "text": "The author's inspector approved declarations without review for 1.5 years and was later reprimanded, prompting a full re‑check of all years' declarations.",
          "evidence": [1]
        },
        {
          "text": "Using Sveta’s help allowed a correct re‑declaration that cost about 1 000 UAH instead of paying all fines.",
          "evidence": [1]
        },
        {
          "text": "The tax calculation procedure typically takes about an hour with Excel, or up to a day for quarterly reports.",
          "evidence": [5,6,7,8]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase as a funding source",
      "claims": [
        {
          "text": "Someone needs to buy a calculator so there will be money for a domain.",
          "evidence": [4]
        },
        {
          "text": "Participant P4 is skeptical about buying a domain, calling the idea “sick” and unsuitable.",
          "evidence": [9,10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Low profitability of a simple web/app product",
      "claims": [
        {
          "text": "Web platforms are the simplest but far less profitable than Android/iOS apps.",
          "evidence": [11]
        },
        {
          "text": "SEO for the web product is poor; the site does not appear even on the 10th Google page.",
          "evidence": [11]
        },
        {
          "text": "There is no external traffic from social platforms, no contextual ads, and app stores promote new apps automatically.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because a paywall appears within the first 10 seconds before the product can demonstrate value.",
          "evidence": [11]
        },
        {
          "text": "Conversion is assumed to be zero; the product does not significantly simplify anything nor integrate with banks or tax cabinets.",
          "evidence": [11]
        },
        {
          "text": "Successful cases involve very fast delivery (under a week) using a cross‑platform stack like Flutter and copying popular ideas with minor tweaks.",
          "evidence": [12]
        },
        {
          "text": "The discussed calculator works only with a UAH‑based FOP; the author had to convert all transactions using the day's exchange rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "password-bundle",
      "title": "Discussion about a password‑protected bundle",
      "claims": [
        {
          "text": "A bundle is sold with a 100 % discount promo code stored locally, making the password easy to find.",
          "evidence": [20]
        },
        {
          "text": "Participants joke about hacking the LinkedIn audience to obtain the password.",
          "evidence": [28]
        },
        {
          "text": "The bundle is described as a “local‑first app” with USD/UAH rate updated every 5 minutes, but the paid features actually reside in the bundle.",
          "evidence": [29]
        },
        {
          "text": "Someone calls the project a “free vibe‑code” with little sense, suggesting only technically knowledgeable people will try to find the password.",
          "evidence": [30,31,32,33,34]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Is there a market of at least ten people willing to pay 299 UAH for the described app?",
      "evidence": [20]
    }
  ]
}
